#!/bin/bash
PSQL="sudo -n -u postgres psql -d crm -Atc"
echo "--- producer_version ---"
echo "predictions:"; $PSQL "select coalesce(producer_version,'(null)'), count(*) from crm_v3_shadow_predictions group by 1"
echo "truths:"; $PSQL "select coalesce(producer_version,'(null)'), count(*) from crm_v3_exhaustive_truth group by 1"
echo "--- truth_completeness ---"
$PSQL "select coalesce(truth_completeness,'(null)'), count(*) from crm_v3_exhaustive_truth group by 1 order by 2 desc"
echo "--- пары по шагам ---"
$PSQL "select count(*) from crm_v3_shadow_predictions p join crm_v3_exhaustive_truth t on p.procurement_id=t.procurement_id and p.research_generation_hash=t.research_generation_hash"
$PSQL "select count(*) from crm_v3_shadow_predictions p join crm_v3_exhaustive_truth t on p.procurement_id=t.procurement_id and p.research_generation_hash=t.research_generation_hash where p.producer_version='v3_real_truth' and t.producer_version='v3_real_truth'"
$PSQL "select count(*) from crm_v3_shadow_predictions p join crm_v3_exhaustive_truth t on p.procurement_id=t.procurement_id and p.research_generation_hash=t.research_generation_hash where p.producer_version='v3_real_truth' and t.producer_version='v3_real_truth' and p.created_at < t.created_at"
$PSQL "select count(*) from crm_v3_shadow_predictions p join crm_v3_exhaustive_truth t on p.procurement_id=t.procurement_id and p.research_generation_hash=t.research_generation_hash where p.producer_version='v3_real_truth' and t.producer_version='v3_real_truth' and p.created_at < t.created_at and t.truth_completeness='COMPLETE'"
echo "--- то же, но с producer_version у материала примеров ---"
$PSQL "select coalesce(producer_version,'(null)'), coalesce(temporal_class,'(null)'), coalesce(label_source,'(null)'), count(*) from crm_v3_learning_examples group by 1,2,3" 
